def P(x,st='Bodyx'): return Paragraph(x,s[st])
def T(headers, rows, widths):
    data=[[P(v,'Headx') for v in headers]]+[[P(str(v),'Cellx') for v in row] for row in rows]
    t=Table(data,colWidths=widths,repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),GREEN),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,LINE),('LEFTPADDING',(0,0),(-1,-1),5),('RIGHTPADDING',(0,0),(-1,-1),5),('TOPPADDING',(0,0),(-1,-1),4),('BOTTOMPADDING',(0,0),(-1,-1),4),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,PALE])]))
    return t
def title(text,lead=None):
    a=[P(text,'H1x'),HRFlowable(width='100%',thickness=1,color=GOLD,spaceAfter=7)]
    if lead:a.append(P(lead))
    return a
def footer(c,d):
    if d.page>1:
        c.saveState();c.setStrokeColor(LINE);c.line(18*mm,14*mm,W-18*mm,14*mm);c.setFont('Helvetica',7);c.setFillColor(MUTED);c.drawString(18*mm,9*mm,'HealthyBite • Project structure and function guide');c.drawRightString(W-18*mm,9*mm,str(d.page));c.restoreState()

